#include <stdio.h>
int main() {
    const int size_kb = 200;
    const int bytes = size_kb * 1024;
    const long bits = (long)bytes * 8;
    const double rate = 10e6; // 10 Mbps
    double trans = bits / rate;
    double total = 0.6 + trans;
    printf("Total time = %.3f s\n", total);
    return 0;
}
